import * as THREE from 'three';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;
const scene=new THREE.Scene();scene.background=new THREE.Color('#17192c');scene.fog=new THREE.FogExp2('#17192c',.022);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);camera.position.set(0,5.6,14.7);
scene.add(new THREE.HemisphereLight(0xc9d9ff,0x382331,2.1));
const moonLight=new THREE.DirectionalLight(0xffddb4,3.2);moonLight.position.set(-5,9,7);moonLight.castShadow=true;moonLight.shadow.mapSize.set(1024,1024);moonLight.shadow.camera.left=-12;moonLight.shadow.camera.right=12;moonLight.shadow.camera.top=12;moonLight.shadow.camera.bottom=-12;scene.add(moonLight);
const rimLight=new THREE.PointLight(0x9268ff,34,18);rimLight.position.set(3,5,-4);scene.add(rimLight);
const fireLight=new THREE.PointLight(0xff6542,19,12);fireLight.position.set(-5,2,2);scene.add(fireLight);
const mat=(color,roughness=.7,metalness=0,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive:emissive?new THREE.Color(color):new THREE.Color(0),emissiveIntensity:emissive});
const floorMat=mat('#25273a',.91),stone=mat('#555068'),darkStone=mat('#28283b'),gold=mat('#edb662',.4,.72),glowGold=mat('#ffb34f',.35,.2,.6),cyan=mat('#56dfff',.35,.1,.7),violet=mat('#9a53ed',.32,.1,.9);
const ground=new THREE.Mesh(new THREE.CircleGeometry(22,80),floorMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.09;ground.receiveShadow=true;scene.add(ground);
const platform=new THREE.Mesh(new THREE.CylinderGeometry(8,8.5,.34,64),mat('#3b3548',.8,.18));platform.position.y=-.21;platform.receiveShadow=true;platform.castShadow=true;scene.add(platform);
const ring=new THREE.Mesh(new THREE.TorusGeometry(7.5,.045,8,100),glowGold);ring.rotation.x=Math.PI/2;ring.position.y=.01;scene.add(ring);
for(let r=1;r<=3;r++){const circle=new THREE.Mesh(new THREE.TorusGeometry(1.05*r,.018,6,64),mat(r%2?'#9d876f':'#77718b',.65,.3));circle.rotation.x=Math.PI/2;circle.position.y=.015;circle.scale.set(1.5,1,1);scene.add(circle)}
// Distant eclipse, layered cliffs, and shattered temple pillars form the arena backdrop.
const moon=new THREE.Mesh(new THREE.CircleGeometry(2.15,64),new THREE.MeshBasicMaterial({color:'#e4a77d'}));moon.position.set(0,7,-13);scene.add(moon);
const moonHalo=new THREE.Mesh(new THREE.TorusGeometry(2.35,.08,12,72),new THREE.MeshBasicMaterial({color:'#a55878',transparent:true,opacity:.65}));moonHalo.position.copy(moon.position);scene.add(moonHalo);
const darkMoon=new THREE.Mesh(new THREE.CircleGeometry(1.88,64),new THREE.MeshBasicMaterial({color:'#262337'}));darkMoon.position.set(.35,7.1,-12.92);scene.add(darkMoon);
for(let i=0;i<34;i++){const x=(Math.random()-.5)*34,z=-9-Math.random()*10,h=1+Math.random()*4;const b=new THREE.Mesh(new THREE.ConeGeometry(.9+Math.random()*1.5,h,5),mat(i%2?'#28283d':'#313044'));b.position.set(x,h/2-1.6,z);b.rotation.z=(Math.random()-.5)*.24;scene.add(b)}
function pillar(x,z,height,broken=false){const base=new THREE.Mesh(new THREE.CylinderGeometry(.72,.86,.35,8),stone);base.position.set(x,.04,z);scene.add(base);const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.52,.62,height,8),stone);shaft.position.set(x,height/2+.18,z);shaft.castShadow=true;shaft.receiveShadow=true;scene.add(shaft);for(let y=.45;y<height;y+=.72){const band=new THREE.Mesh(new THREE.TorusGeometry(.56,.07,6,8),gold);band.position.set(x,y,z);band.rotation.x=Math.PI/2;scene.add(band)}const cap=new THREE.Mesh(new THREE.BoxGeometry(1.5,.25,1.5),stone);cap.position.set(x,height+.25,z);if(broken){cap.rotation.z=.27;cap.position.y=height-.1}scene.add(cap)}
for(const x of [-9,-6.8,6.8,9])pillar(x,-4.5,4+(Math.random()*2),Math.abs(x)>8);
// Glowing embers hang in the air as lightweight, animated particles.
const emberMat=new THREE.MeshBasicMaterial({color:'#ffad68'}),embers=[];for(let i=0;i<70;i++){const e=new THREE.Mesh(new THREE.SphereGeometry(.025+Math.random()*.025,6,6),emberMat);e.position.set((Math.random()-.5)*17,Math.random()*6-0.3,(Math.random()-.5)*9-2);scene.add(e);embers.push({mesh:e,phase:Math.random()*9,speed:.3+Math.random()*.75})}

const sphereGeo=new THREE.SphereGeometry(1,16,12),boxGeo=new THREE.BoxGeometry(1,1,1);
function ball(parent,name,color,pos,scale,material){const m=new THREE.Mesh(sphereGeo,material||mat(color,.62));m.name=name;m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeFighter(isPlayer){const root=new THREE.Group();scene.add(root);const model=new THREE.Group();root.add(model);const colors=isPlayer?{cloth:'#e95237',dark:'#332236',hair:'#202437',skin:'#e9ad83',accent:'#ffcf69',energy:'#ff874d'}:{cloth:'#52319a',dark:'#252038',hair:'#d8d2ea',skin:'#a8a0cc',accent:'#c378ff',energy:'#ba5cff'};const cloth=mat(colors.cloth,.54),dark=mat(colors.dark,.57),hair=mat(colors.hair,.44),skin=mat(colors.skin,.64),accent=mat(colors.accent,.35,.42),energy=mat(colors.energy,.3,.2,.8);root.userData={isPlayer,colors,energyMat:energy};
// Feet, long boots, layered tunic, torso and shoulder armor.
ball(model,'belt',colors.accent,[0,1.12,0],[.47,.12,.3],accent);
for(const s of [-1,1]){const leg=new THREE.Group();leg.position.set(s*.22,.92,0);model.add(leg);root.userData[s<0?'legL':'legR']=leg;ball(leg,'trouser',colors.dark,[0,-.25,0],[.18,.39,.2],dark);ball(leg,'boot',colors.cloth,[0,-.52,.045],[.2,.17,.27],cloth);const cuff=ball(leg,'cuff',colors.accent,[0,-.43,.04],[.205,.07,.22],accent)}
ball(model,'tunic',colors.cloth,[0,1.44,0],[.43,.5,.28],cloth);ball(model,'chest',colors.accent,[0,1.55,.252],[.26,.17,.055],accent);
for(let s of [-1,1])ball(model,'shoulder',colors.accent,[s*.43,1.72,0],[.23,.19,.24],accent);
const head=new THREE.Group();head.position.set(0,2.08,0);model.add(head);root.userData.head=head;ball(head,'face',colors.skin,[0,0,0],[.25,.31,.23],skin);
ball(head,'haircap',colors.hair,[0,.17,-.025],[.28,.2,.25],hair);
for(let i=0;i<7;i++){const spike=new THREE.Mesh(new THREE.ConeGeometry(.11,.38,5),hair);spike.position.set((i-3)*.075,.36+Math.random()*.08,(i%2)*.07);spike.rotation.z=(i-3)*-.21;spike.rotation.x=-.25;spike.castShadow=true;head.add(spike)}
for(let s of [-1,1]){ball(head,'eye',isPlayer?'#3ce4f6':'#edb7ff',[s*.105,.015,.204],[.05,.033,.027],mat(isPlayer?'#51f4ff':'#ffa6ff',.25,0,1));}
const arms=[];for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.48,1.69,0);model.add(arm);root.userData[s<0?'armL':'armR']=arm;arms.push(arm);ball(arm,'upper',colors.cloth,[s*.06,-.2,0],[.17,.29,.17],cloth);const bracer=ball(arm,'bracer',colors.accent,[s*.1,-.38,.025],[.18,.13,.19],accent);ball(arm,'fist',colors.skin,[s*.1,-.51,.045],[.14,.14,.14],skin)}
const scarf=ball(model,'scarf',colors.accent,[0,1.86,-.18],[.32,.1,.18],accent);const tail=new THREE.Mesh(new THREE.ConeGeometry(.12,.95,6),cloth);tail.position.set(-.37,1.4,-.23);tail.rotation.z=.8;model.add(tail);root.userData.tail=tail;
const aura=new THREE.Mesh(new THREE.SphereGeometry(.76,20,16),new THREE.MeshBasicMaterial({color:colors.energy,transparent:true,opacity:0,depthWrite:false,wireframe:true}));aura.position.y=1.4;model.add(aura);root.userData.aura=aura;
root.userData.model=model;root.userData.arms=arms;root.userData.mats=[cloth,dark,accent,energy];return root}
const player=makeFighter(true),enemy=makeFighter(false);player.position.set(-2.2,0,0);enemy.position.set(2.2,0,-.35);player.rotation.y=0;enemy.rotation.y=Math.PI;
const fighters={player,enemy};

const state={active:true,round:1,pWins:0,eWins:0,time:99,player:{hp:100,ki:30,charge:0,x:-2.2,y:0,vx:0,vy:0,grounded:true,blocking:false,attack:0,attackCd:0,hitstun:0,facing:1,transform:0,transformed:0,anim:0},enemy:{hp:100,ki:30,charge:0,x:2.2,y:0,vx:0,vy:0,grounded:true,blocking:false,attack:0,attackCd:0,hitstun:0,facing:-1,transform:0,transformed:0,anim:0},projectiles:[],effects:[],aiTimer:1.2,lastTime:0};
const $=s=>document.querySelector(s),ui={pHealth:$('#pHealth'),eHealth:$('#eHealth'),pKi:$('#pKi'),eKi:$('#eKi'),timer:$('#timer'),title:$('#messageTitle'),sub:$('#messageSub'),message:$('#message'),charge:$('#transformFill'),chargeText:$('#transformText'),pWins:$('#pWins'),eWins:$('#eWins'),enemyName:$('#enemyName'),enemyTitle:$('#enemyTitle'),stage:$('#stageName')};
const keys=new Set(),held=new Set();let audioCtx=null,soundOn=false;
function sound(freq=180,duration=.08,type='sawtooth',volume=.035){if(!soundOn)return;try{audioCtx ||= new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function setMessage(title,sub,kicker='EL DESTINO SE DECIDE',time=1.4){ui.title.textContent=title;ui.sub.textContent=sub;ui.message.querySelector('.msg-kicker').textContent=kicker;ui.message.classList.remove('hidden');clearTimeout(setMessage.t);if(time)setMessage.t=setTimeout(()=>ui.message.classList.add('hidden'),time*1000)}
function spawnEffect(x,y,z,color,size=1){const group=new THREE.Group();group.position.set(x,y,z);scene.add(group);const material=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85,wireframe:true});const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(size,1),material);group.add(mesh);state.effects.push({group,mesh,life:.45,max:.45})}
function projectile(fromPlayer){const f=fromPlayer?state.player:state.enemy,root=fromPlayer?player:enemy,col=fromPlayer?0xffa45c:0xc07bff;const p=new THREE.Mesh(new THREE.IcosahedronGeometry(.27,1),new THREE.MeshBasicMaterial({color:col}));p.position.set(f.x+f.facing*.65,1.48+f.y,0);scene.add(p);const auraMesh=new THREE.Mesh(new THREE.SphereGeometry(.42,12,10),new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.23}));p.add(auraMesh);state.projectiles.push({mesh:p,owner:fromPlayer?'player':'enemy',x:p.position.x,v:f.facing*9,life:1.7,damage:fromPlayer?16:12});spawnEffect(p.position.x,1.5,0,col,.45);sound(fromPlayer?430:250,.18,'triangle',.05)}
function attack(who){const f=state[who],root=fighters[who],other=who==='player'?'enemy':'player';if(!state.active||f.attackCd>0||f.hitstun>0)return;if(f.ki<3)return;f.ki=Math.max(0,f.ki-3);f.attack=.29;f.attackCd=.44;f.charge=Math.min(100,f.charge+8);f.ki=Math.min(100,f.ki+5);f.anim=0;spawnEffect(f.x+f.facing*.65,1.45+f.y,0,who==='player'?0xffc56e:0xcb75ff,.45);sound(who==='player'?290:190,.09);const target=state[other],distance=Math.abs(f.x-target.x);if(distance<1.6&&Math.abs(f.y-target.y)<1.7){if(target.blocking){target.hp=Math.max(0,target.hp-2);target.ki=Math.min(100,target.ki+5);sound(100,.07,'square',.025)}else{target.hp=Math.max(0,target.hp-9-(f.transformed?4:0));target.hitstun=.34;target.vx=f.facing*2.6;target.ki=Math.min(100,target.ki+8);target.charge=Math.min(100,target.charge+7);spawnEffect(target.x,1.5+target.y,0,who==='player'?0xffd26e:0xc778ff,.7);sound(105,.16,'square',.05)}}}
function blast(who){const f=state[who];if(!state.active||f.ki<24||f.attackCd>.15||f.hitstun>0)return;f.ki-=24;f.charge=Math.min(100,f.charge+13);f.attackCd=.55;f.attack=.35;projectile(who==='player');}
function jump(who){const f=state[who];if(!state.active||f.hitstun>0)return;if(f.grounded){f.vy=7.6;f.grounded=false;sound(300,.06,'sine',.02)}else if(f.transformed&&f.y<3){f.vy=3.1}}
function transform(who){const f=state[who],root=fighters[who];if(!state.active||f.transformed>0||f.charge<100)return;f.charge=0;f.transformed=8;f.hp=Math.min(100,f.hp+12);f.ki=Math.min(100,f.ki+30);root.userData.aura.material.opacity=.28;root.userData.aura.scale.setScalar(1.6);spawnEffect(f.x,1.4+f.y,0,who==='player'?0xffa94f:0xc276ff,1.3);setMessage('¡ASCENSIÓN!','PODER ELEMENTAL DESATADO','TRANSFORMACIÓN',1.8);sound(520,.45,'sawtooth',.06)}
function action(actionName,down=true){if(actionName==='left'||actionName==='right'||actionName==='block'){down?held.add(actionName):held.delete(actionName);return}if(!down)return;if(actionName==='punch')attack('player');if(actionName==='power')blast('player');if(actionName==='jump')jump('player');if(actionName==='transform')transform('player')}
for(const button of document.querySelectorAll('[data-action]')){const actionName=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.classList.add('pressed');button.setPointerCapture?.(e.pointerId);action(actionName,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,e=>{button.classList.remove('pressed');if(['left','right','block'].includes(actionName))action(actionName,false)})}
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' '].includes(key))e.preventDefault();keys.add(key);if(e.repeat)return;if(key==='j'||key==='f')attack('player');if(key==='k'||key==='g')blast('player');if(key===' '||key==='w'||key==='arrowup')jump('player');if(key==='l'||key==='t')transform('player');if(key==='shift')held.add('block')});window.addEventListener('keyup',e=>{const key=e.key.toLowerCase();keys.delete(key);if(key==='shift')held.delete('block')});
$('#soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('#soundBtn').innerHTML=soundOn?'♫ <span>SONIDO ON</span>':'♫ <span>SONIDO</span>';if(soundOn)sound(440,.1,'sine')});$('#restartBtn').addEventListener('click',()=>startFight(true));
function startFight(resetScores=false){if(resetScores){state.pWins=0;state.eWins=0;state.round=1}state.active=true;state.time=99;for(const n of ['player','enemy']){const f=state[n];Object.assign(f,{hp:100,ki:32,charge:0,x:n==='player'?-2.2:2.2,y:0,vx:0,vy:0,grounded:true,blocking:false,attack:0,attackCd:0,hitstun:0,facing:n==='player'?1:-1,transform:0,transformed:0,anim:0})}player.position.set(-2.2,0,0);enemy.position.set(2.2,0,-.35);state.projectiles.forEach(p=>scene.remove(p.mesh));state.projectiles=[];ui.stage.textContent=state.round===1?'SANTUARIO DEL ECLIPSE':state.round===2?'FORJA DEL ABISMO':'TRONO DE LOS DIOSES';ui.enemyName.textContent=state.round===1?'VEX':state.round===2?'MORGA':'AZRAEL';ui.enemyTitle.textContent=state.round===1?'SEÑOR DEL VACÍO':state.round===2?'TITÁN DE CENIZA':'DIOS DEL CAOS';enemy.userData.mats[0].color.set(state.round===1?'#52319a':state.round===2?'#8a392c':'#29384d');enemy.userData.energyMat.color.set(state.round===1?'#ba5cff':state.round===2?'#ff633a':'#51ceff');enemy.userData.energyMat.emissive.set(state.round===1?'#ba5cff':state.round===2?'#ff633a':'#51ceff');ui.pWins.textContent=state.pWins;ui.eWins.textContent=state.eWins;setMessage('¡LUCHEN!','DERROTA AL '+ui.enemyName.textContent,'EL DESTINO SE DECIDE',1.6);state.aiTimer=.8}
function finishRound(winner){state.active=false;if(winner==='player'){state.pWins++;ui.pWins.textContent=state.pWins;setMessage('¡VICTORIA!','EL CAOS SE INCLINA ANTE TI','RONDA CONQUISTADA',0);if(state.pWins>=2){setMessage('¡CAMPEÓN!','HAS DOMINADO EL CAOS','LEYENDA NACIDA',0);return}}else{state.eWins++;ui.eWins.textContent=state.eWins;setMessage('DERROTA','EL VACÍO TE RECLAMA','RONDA PERDIDA',0);if(state.eWins>=2){setMessage('FIN DEL COMBATE','EL CAOS HA TRIUNFADO','INTÉNTALO DE NUEVO',0);return}}state.round++;setTimeout(()=>startFight(),1900)}
function updateFighter(who,dt,time){const f=state[who],root=fighters[who],op=state[who==='player'?'enemy':'player'];f.anim+=dt;f.attack=Math.max(0,f.attack-dt);f.attackCd=Math.max(0,f.attackCd-dt);f.hitstun=Math.max(0,f.hitstun-dt);f.transformed=Math.max(0,f.transformed-dt);if(f.transformed<=0){root.userData.aura.material.opacity=0;root.userData.aura.scale.setScalar(1)}
if(who==='player'){let move=0;if(keys.has('a')||keys.has('arrowleft')||held.has('left'))move-=1;if(keys.has('d')||keys.has('arrowright')||held.has('right'))move+=1;if(Math.abs(f.x-op.x)<.8&&move===Math.sign(op.x-f.x))move=0;f.blocking=held.has('block')||keys.has('shift');if(f.hitstun<=0&&move){f.x+=move*4.2*dt;f.facing=move;f.ki=Math.min(100,f.ki+dt*1.1)} }else{f.blocking=false;state.aiTimer-=dt;if(f.hitstun<=0){const dist=op.x-f.x;f.facing=Math.sign(dist)||-1;if(Math.abs(dist)>1.35){f.x+=Math.sign(dist)*2.1*dt;f.ki=Math.min(100,f.ki+dt*1.35)}else if(state.aiTimer<=0){const r=Math.random();if(f.ki>40&&r<.28)blast('enemy');else if(r<.48&&f.charge>=100)transform('enemy');else if(r<.63)jump('enemy');else{if(Math.random()<.36)f.blocking=true;setTimeout(()=>{if(state.active){f.blocking=false;attack('enemy')}},180)}state.aiTimer=.7+Math.random()*.8}}}
if(f.hitstun>0)f.x+=f.vx*dt*0.52;f.vx*=Math.exp(-8*dt);f.vy-=17*dt;f.y+=f.vy*dt;if(f.y<0){f.y=0;f.vy=0;f.grounded=true}f.x=THREE.MathUtils.clamp(f.x,-6.7,6.7);if(Math.abs(f.x-op.x)<.72){f.x+=f.x<op.x?-.02:.02}
root.position.set(f.x,f.y,who==='player'?0:-.35);root.rotation.y=f.facing>0?0:Math.PI;const m=root.userData.model;m.position.y=Math.sin(time*8+ (who==='player'?0:1))*.035+(f.grounded?0:0);const arms=root.userData.arms,attackAngle=f.attack>0?-.95:0;root.userData.armL.rotation.z=attackAngle;root.userData.armR.rotation.z=attackAngle;root.userData.armL.rotation.x=f.blocking?-.6:Math.sin(time*6)*.045;root.userData.armR.rotation.x=f.blocking?-.6:Math.sin(time*6+1)*.045;root.userData.legL.rotation.x=f.grounded?Math.sin(time*8+(who==='player'?0:Math.PI))*Math.min(.22,Math.abs(f.vx)*.04):-.45;root.userData.legR.rotation.x=f.grounded?-root.userData.legL.rotation.x:.4;root.userData.tail.rotation.z=.8+Math.sin(time*3)*.12;root.userData.head.rotation.z=f.hitstun>0?.16:0;
if(f.attack>0){root.userData.armR.rotation.z=-1.55;root.userData.armR.rotation.x=-.45}if(f.blocking){root.userData.aura.material.opacity=.07;root.userData.aura.scale.setScalar(1.1)}else if(!f.transformed){root.userData.aura.material.opacity=0}}
function update(dt,time){for(const e of embers){e.mesh.position.y+=Math.sin(time*e.speed+e.phase)*dt*.15;e.mesh.position.x+=Math.sin(time*.4+e.phase)*dt*.12}
if(state.active){state.time=Math.max(0,state.time-dt);if(state.time===0)finishRound(state.player.hp>=state.enemy.hp?'player':'enemy');updateFighter('player',dt,time);updateFighter('enemy',dt,time);if(state.player.hp<=0)finishRound('enemy');else if(state.enemy.hp<=0)finishRound('player')}
for(let i=state.projectiles.length-1;i>=0;i--){const p=state.projectiles[i];p.x+=p.v*dt;p.mesh.position.x=p.x;p.mesh.rotation.x+=dt*8;p.mesh.rotation.y+=dt*5;p.life-=dt;const target=p.owner==='player'?state.enemy:state.player;if(Math.abs(p.x-target.x)<.48&&Math.abs((p.mesh.position.y||1.5)-(1.45+target.y))<1.1){if(!target.blocking){target.hp=Math.max(0,target.hp-p.damage-(target.transformed?5:0));target.hitstun=.42;target.vx=Math.sign(p.v)*3;target.charge=Math.min(100,target.charge+10);target.ki=Math.min(100,target.ki+10);spawnEffect(target.x,1.45+target.y,0,p.owner==='player'?0xffb95f:0xc279ff,1)}else target.ki=Math.min(100,target.ki+8);p.life=0;spawnEffect(p.x,1.5,0,p.owner==='player'?0xffb65d:0xc27bff,.65)}if(p.life<=0||Math.abs(p.x)>10){scene.remove(p.mesh);state.projectiles.splice(i,1)}}
