 root.position.set(f.x,f.y,who==='player'?0:-.35);root.rotation.y=f.facing*.48;const m=root.userData.model;m.position.y=Math.sin(time*8+ (who==='player'?0:1))*.035+(f.grounded?0:0);const arms=root.userData.arms,attackAngle=f.attack>0?-.95:0;root.userData.armL.rotation.z=attackAngle;root.userData.armR.rotation.z=attackAngle;root.userData.armL.rotation.x=f.blocking?-.6:Math.sin(time*6)*.045;root.userData.armR.rotation.x=f.blocking?-.6:Math.sin(time*6+1)*.045;root.userData.legL.rotation.x=f.grounded?Math.sin(time*8+(who==='player'?0:Math.PI))*Math.min(.22,Math.abs(f.vx)*.04):-.45;root.userData.legR.rotation.x=f.grounded?-root.userData.legL.rotation.x:.4;root.userData.tail.rotation.z=.8+Math.sin(time*3)*.12;root.userData.head.rotation.z=f.hitstun>0?.16:0;
 if(f.attack>0){root.userData.armR.rotation.z=-1.55;root.userData.armR.rotation.x=-.45}if(f.blocking){root.userData.aura.material.opacity=.07;root.userData.aura.scale.setScalar(1.1)}else if(!f.transformed){root.userData.aura.material.opacity=0}}
 function update(dt,time){for(const e of embers){e.mesh.position.y+=Math.sin(time*e.speed+e.phase)*dt*.15;e.mesh.position.x+=Math.sin(time*.4+e.phase)*dt*.12}
 if(state.active){state.time=Math.max(0,state.time-dt);if(state.time===0)finishRound(state.player.hp>=state.enemy.hp?'player':'enemy');updateFighter('player',dt,time);updateFighter('enemy',dt,time);if(state.player.hp<=0)finishRound('enemy');else if(state.enemy.hp<=0)finishRound('player')}

